import { Controller, Post, Body, HttpException, HttpStatus } from '@nestjs/common';
import { DynamoDBClient, GetItemCommand, PutItemCommand } from '@aws-sdk/client-dynamodb';
import * as crypto from 'crypto';

const ALGORITHM = 'aes-256-cbc';
const KEY = Buffer.from(process.env.ENCRYPTION_KEY || 'a'.repeat(64), 'hex');

interface DecryptRequest {
  userId: string;
  encryptedToken: string; // hex encoded: IV (16 bytes) + ciphertext + padding
}

interface TokenPayload {
  sub: string;
  scope: string;
  exp: number;
}

@Controller('api/v2/tokens')
export class TokenController {
  private dynamoClient: DynamoDBClient;

  constructor() {
    this.dynamoClient = new DynamoDBClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });
  }

  @Post('validate')
  async validateToken(@Body() req: DecryptRequest) {
    const { userId, encryptedToken } = req;

    if (!userId || !encryptedToken) {
      throw new HttpException('Missing required fields', HttpStatus.BAD_REQUEST);
    }

    // Retrieve user's token record from DynamoDB for comparison
    const getCmd = new GetItemCommand({
      TableName: 'UserTokens',
      Key: {
        'PK': { S: `USER#${userId}` },
        'SK': { S: 'TOKEN#current' },
      },
    });

    const record = await this.dynamoClient.send(getCmd);
    if (!record.Item) {
      throw new HttpException('Token record not found', HttpStatus.NOT_FOUND);
    }

    // Decrypt the submitted token
    let decrypted: Buffer;
    try {
      const raw = Buffer.from(encryptedToken, 'hex');
      const iv = raw.subarray(0, 16);
      const ciphertext = raw.subarray(16);

      const decipher = crypto.createDecipheriv(ALGORITHM, KEY, iv);
      // VULNERABILITY: Padding errors produce distinct error vs other failures
      const part1 = decipher.update(ciphertext);
      const part2 = decipher.final(); // throws on bad padding
      decrypted = Buffer.concat([part1, part2]);
    } catch (err: any) {
      // Padding oracle: different error message for padding vs format errors
      if (err.message.includes('bad decrypt') || err.message.includes('wrong final block')) {
        throw new HttpException(
          'Decryption failed: invalid padding',
          HttpStatus.UNPROCESSABLE_ENTITY  // 422
        );
      }
      throw new HttpException(
        'Decryption failed: malformed input',
        HttpStatus.BAD_REQUEST  // 400
      );
    }

    // Parse and validate token payload
    let payload: TokenPayload;
    try {
      payload = JSON.parse(decrypted.toString('utf8'));
    } catch {
      throw new HttpException('Invalid token format', HttpStatus.BAD_REQUEST);
    }

    if (payload.sub !== userId) {
      throw new HttpException('Token subject mismatch', HttpStatus.FORBIDDEN);
    }

    if (payload.exp < Date.now() / 1000) {
      throw new HttpException('Token expired', HttpStatus.UNAUTHORIZED);
    }

    // Log successful validation
    await this.dynamoClient.send(new PutItemCommand({
      TableName: 'TokenAuditLog',
      Item: {
        'PK': { S: `USER#${userId}` },
        'SK': { S: `VALIDATION#${Date.now()}` },
        'status': { S: 'SUCCESS' },
        'scope': { S: payload.scope },
      },
    }));

    return { valid: true, scope: payload.scope };
  }
}
